-- A newer self-description cannot overwrite a previously reviewed task capability.
create or replace function private.development_programme_report(p_cohort text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare population integer; rows jsonb;
begin
 if auth.uid() is null or not private.can_view_competency_cohort(p_cohort) then raise insufficient_privilege using message='Programme access is required.';end if;
 select count(distinct cm.learner_user_id)::integer into population from public.cohort_members cm join public.learners l on l.user_id=cm.learner_user_id and l.status='ACTIVE' join public.pilot_cohorts pc on pc.id=cm.cohort_id and pc.status='ACTIVE'
 where cm.cohort_id=p_cohort and cm.status='ACTIVE' and (select status from public.consent_records cr where cr.user_id=cm.learner_user_id and cr.consent_type='LEARNER_PRODUCT' order by cr.created_at desc,cr.id desc limit 1)='GRANTED';
 if population<5 then return jsonb_build_object('cohortId',p_cohort,'participantCount',population,'suppressed',true,'competencies','[]'::jsonb);end if;
 with facts as(select * from private.current_development_reviews() where cohort_id=p_cohort and reporting_allowed),
 current_fact as(select distinct on(user_id,competency_id) * from facts order by user_id,competency_id,(source_nature='ASSESSED_TASK') desc,at desc,review_id desc),
 person as(select f.*,b.stage as baseline_stage,b.at as baseline_at,a.perception_level as first_perception,a.stage as first_alignment_stage,a.at as first_alignment_at,
  (f.source_nature='ASSESSED_TASK') as assessed_only,
  (select count(*) from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.source_nature=f.source_nature) as reviews,
  (select count(distinct x.at::date) from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.source_nature=f.source_nature and x.independent and private.development_stage_level(x.stage)>=3) as independent_days,
  exists(select 1 from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.source_nature=f.source_nature and x.stage='TRANSFER') as has_transfer,
  exists(select 1 from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.source_nature=f.source_nature and x.independent and private.development_stage_level(x.stage)>=3 and f.follow_up_days is not null and x.at>=(select min(ap.at) from facts ap where ap.user_id=f.user_id and ap.competency_id=f.competency_id and ap.comparison_key=f.comparison_key and ap.source_nature=f.source_nature and ap.independent and private.development_stage_level(ap.stage)>=3)+f.follow_up_days*interval '1 day') as has_followup
 from current_fact f join lateral(select * from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.source_nature=f.source_nature order by x.at,x.review_id limit 1) b on true left join lateral(select x.perception_level,x.stage,x.at from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.source_nature=f.source_nature and x.perception_level is not null and x.source_nature='ASSESSED_TASK' order by x.at,x.review_id limit 1) a on true),
 partitions as(
 select competency_id,'distribution' as kind,stage as code,count(*)::integer as n from person group by competency_id,stage
 union all select competency_id,'baselineDistribution',baseline_stage,count(*)::integer from person group by competency_id,baseline_stage
 union all select competency_id,'changeDistribution',case when baseline_at>=at then 'INSUFFICIENT_HISTORY' when private.development_stage_level(stage)>private.development_stage_level(baseline_stage) then 'HIGHER_REVIEWED_STAGE' when private.development_stage_level(stage)<private.development_stage_level(baseline_stage) then 'LOWER_REVIEWED_STAGE' else 'SAME_REVIEWED_STAGE' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,'strengthDistribution',case when assessed_only and reviews>=3 and independent_days>=3 then 'STRONG' when reviews>=2 then 'MODERATE' else 'LIMITED' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,'sourceDistribution',case when assessed_only then 'ASSESSED_TASK' else 'SELF_REPORT' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,'alignmentDistribution',case when source_nature<>'ASSESSED_TASK' or perception_level is null then 'NO_COMPATIBLE_COMPARISON' when abs(perception_level-private.development_stage_level(stage))=0 then 'SAME_STAGE' when abs(perception_level-private.development_stage_level(stage))=1 then 'ONE_STAGE_APART' else 'TWO_OR_MORE_STAGES_APART' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,'alignmentChangeDistribution',case when source_nature<>'ASSESSED_TASK' or first_alignment_at>=at or perception_level is null or first_perception is null then 'NO_COMPATIBLE_PAIR' when abs(perception_level-private.development_stage_level(stage))<abs(first_perception-private.development_stage_level(first_alignment_stage)) then 'SMALLER_GAP' when abs(perception_level-private.development_stage_level(stage))>abs(first_perception-private.development_stage_level(first_alignment_stage)) then 'LARGER_GAP' else 'SAME_GAP' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,kind,case when kind in ('distribution','baselineDistribution') then 'NOT_YET_EVIDENCED' when kind='alignmentDistribution' then 'NO_COMPATIBLE_COMPARISON' when kind='alignmentChangeDistribution' then 'NO_COMPATIBLE_PAIR' else 'NO_REVIEWED_EVIDENCE' end,population-count(*)::integer from person cross join unnest(array['distribution','baselineDistribution','changeDistribution','strengthDistribution','sourceDistribution','alignmentDistribution','alignmentChangeDistribution']) kind group by competency_id,kind),
 partition_values as(select competency_id,kind,private.development_safe_partition(jsonb_agg(jsonb_build_object('code',code,'count',n) order by code),population) as value from(select competency_id,kind,code,sum(n)::integer n from partitions group by competency_id,kind,code) p group by competency_id,kind),
 totals as(select competency_id,count(*)::integer as covered,sum(reviews)::integer as evidence_count,count(*) filter(where assessed_only and has_transfer)::integer as transferred,count(*) filter(where assessed_only and independent_days>=3)::integer as repeated,count(*) filter(where assessed_only and has_followup)::integer as followup,count(*) filter(where assessed_only and perception_level is not null)::integer as alignment,count(*) filter(where assessed_only and baseline_at<at and private.development_stage_level(stage)>private.development_stage_level(baseline_stage))::integer as assessed_growth from person group by competency_id),
 calendar as(select g as period from public.pilot_cohorts c cross join lateral generate_series(greatest(date_trunc('month',coalesce(c.starts_on::timestamptz,now()-interval '11 months')),date_trunc('month',now()-interval '11 months')),date_trunc('month',least(coalesce(c.ends_on::timestamptz,now()),now())),interval '1 month') g where c.id=p_cohort),
 snapshots as(select t.competency_id,calendar.period,(select count(*)::integer from (select distinct on(x.user_id) x.stage,x.source_nature from facts x where x.competency_id=t.competency_id and x.at<calendar.period+interval '1 month' order by x.user_id,(x.source_nature='ASSESSED_TASK') desc,x.at desc,x.review_id desc) latest where latest.source_nature='ASSESSED_TASK' and private.development_stage_level(latest.stage)>=3) as applied from totals t cross join calendar),
 safe as(select t.* from totals t where not exists(select 1 from partition_values p where p.competency_id=t.competency_id and p.kind in ('distribution','changeDistribution','strengthDistribution') and p.value is null) and not exists(select 1 from unnest(array[t.covered,population-t.covered,t.transferred,population-t.transferred,t.repeated,population-t.repeated,t.followup,population-t.followup,t.alignment,population-t.alignment]) n where n between 1 and 2))
 select coalesce(jsonb_agg(jsonb_build_object('competencyId',t.competency_id,'distribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='distribution'),'changeDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='changeDistribution'),'strengthDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='strengthDistribution'),'baselineDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='baselineDistribution'),'sourceDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='sourceDistribution'),'alignmentDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='alignmentDistribution'),'alignmentChangeDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='alignmentChangeDistribution'),'transferParticipants',t.transferred,'repeatedApplicationParticipants',t.repeated,'followupParticipants',t.followup,'alignmentParticipants',t.alignment,'evidenceCount',t.evidence_count,'assessedGrowthParticipants',case when t.assessed_growth between 1 and 2 or population-t.assessed_growth between 1 and 2 then null else t.assessed_growth end,'trajectory',(select coalesce(jsonb_agg(jsonb_build_object('period',to_char(s.period,'YYYY-MM'),'assessedApplicationParticipants',case when s.applied between 1 and 2 or population-s.applied between 1 and 2 then null else s.applied end) order by s.period),'[]'::jsonb) from snapshots s where s.competency_id=t.competency_id)) order by t.competency_id),'[]'::jsonb) into rows from safe t;
 return jsonb_build_object('cohortId',p_cohort,'participantCount',population,'suppressed',false,'competencies',rows,'assessmentCount',(select case when count(distinct r.review_id)>=3 then count(distinct r.review_id) else null end from private.current_development_reviews() r where r.cohort_id=p_cohort and r.reporting_allowed and exists(select 1 from jsonb_array_elements(rows) a where a->>'competencyId'=r.competency_id)));
end $$;
